"""Explain decoding, modulo slots, overlap and candidate filtering."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1697': ('여러 항목을 한 줄에 적은 기록에서 필요한 칸을 하나씩 꺼내요. 쓰기 표시가 켜져 있는지는 큰 숫자 자체보다 켜짐과 꺼짐 두 가지로 답하면 편해요.', '압축 기록에서 주소 일부·길이·쓰기 여부를 꺼내는 과정을 이해합니다.', '연습용 8비트 기록 10110110을 쓰기1·길이011·주소0110으로 나누세요. 실제 커널의 비트 수와 다른 작은 모형이라고 적으세요.', ['decode는 정해진 모양으로 담아 둔 기록을 다시 풀어 읽는 일이에요. decode_watchpoint는 감시 기록에서 주소 일부, 접근 길이, 쓰기 여부를 꺼내요. 먼저 특별한 상태 값 0과 1은 정상 기록으로 읽지 않고 false로 돌아가요.', '쓰기 표시는 정수의 맨 위 비트에 있어요. 이 비트가 켜지면 부호 있는 long으로 볼 때 음수처럼 보일 수 있어요. 그렇다고 감시 기록이 무조건 잘못됐다는 뜻은 아니에요. 여기서는 정수의 양수·음수보다 각 비트에 담긴 의미가 중요해요.', '본문은 기록을 unsigned long, 즉 부호 없는 정수로 바꾼 뒤 필요한 칸을 골라요. 주소 마스크와 &를 하면 아래쪽 주소 칸만 남아요. 길이 마스크와 &를 한 뒤 오른쪽으로 밀면 길이가 원래 숫자 위치로 내려와요. >>는 비트들을 오른쪽으로 옮기는 연산이에요.', '작은 8비트 모형에서 기록 10110110을 쓰기 1칸·길이 3칸·주소 4칸으로 나눠 보세요. 맨 위 쓰기 표시는 1, 길이는 011이라서 3, 주소 부분은 0110이라서 6이에요. 이것은 계산 연습용 배치이며 실제 커널의 비트 폭은 설정에 따라 따로 계산해요.', '쓰기 여부는 !!로 0 또는 1로 만들어요. !는 값이 0이면 1, 0이 아니면 0을 만드는 연산이에요. 그러므로 !!0은 0이고 !!128은 1이에요. 마스크 결과가 큰 숫자라도 쓰기 표시가 켜졌는지를 참·거짓으로 다룰 수 있어요. 메모리 주소를 따라가는 역참조 연산이 아니에요.', '출력 이름 addr_masked처럼 주소는 마스크로 남긴 부분만 나와요. 압축할 때 버린 위쪽 주소 비트를 되살리는 함수는 아니에요. 이 값을 원래 객체의 완전한 주소라고 여기고 메모리를 읽으려고 하면 안 돼요. 이 기록은 접근 후보를 비교하는 데 쓰는 정보예요.'], [('decode가 내놓는 주소는 원래 전체 주소인가요?', ['네. 버렸던 위쪽 비트까지 자동으로 되살려요', '아니요. 마스크로 남긴 주소 부분이에요'], '정답은 두 번째예요. addr_masked는 저장했던 아래쪽 주소 부분이에요. 기록에 남기지 않은 위쪽 비트는 이 값 하나로 복구할 수 없어요.'), ('쓰기 표시를 참·거짓으로 바꾸는 연산은 무엇인가요?', ['!!예요', '포인터를 따라 메모리를 읽는 역참조예요'], '정답은 첫 번째예요. !!는 0이면 0, 0이 아니면 1로 바꿔요. 예를 들어 쓰기 마스크 결과가 128이어도 !!128은 1이므로 표시가 켜졌음을 나타내요.')]), 'os1698': ('많은 책을 몇 개 안 되는 서랍에 나눠 넣으면 서로 다른 책도 같은 서랍에 들어가요. 서랍 번호가 같다고 같은 책은 아니에요.', '페이지 번호와 나머지로 슬롯을 고르는 계산을 이해합니다.', '페이지 4096바이트·슬롯 64개로 놓고 주소4096,4097,266240의 페이지 번호와 슬롯 번호를 계산하세요.', ['slot은 감시 기록을 넣고 찾아보는 자리예요. watchpoint_slot은 주소를 어느 자리와 연결할지 계산해요. 식은 (addr / PAGE_SIZE) % CONFIG_KCSAN_NUM_WATCHPOINTS예요. 먼저 페이지 번호를 구한 다음 슬롯 번호를 구하는 두 단계예요.', '페이지는 메모리를 일정한 크기로 나눈 덩어리예요. 한 페이지가 4096바이트라면 주소 4096부터 8191까지는 페이지 번호 1이에요. 정수 나눗셈에서는 소수점 아래를 버리므로 4096/4096과 4097/4096은 둘 다 1이 돼요.', '%는 나눗셈의 나머지를 구하는 기호예요. 슬롯이 64개라면 페이지 번호를 64로 나눈 나머지를 써요. 1%64=1이므로 페이지 1의 주소들은 슬롯 1과 연결돼요. 바이트마다 서로 다른 슬롯을 주는 방식은 아니에요.', '페이지 65의 시작 주소는 65×4096=266240이에요. 65%64도 1이므로 페이지 1과 페이지 65는 같은 슬롯을 골라요. 두 페이지 번호의 차이가 슬롯 수 64라서 나머지가 다시 같아진 것이에요. 이렇게 다른 주소가 같은 자리를 고르는 것을 슬롯 충돌이라고 불러요.', '슬롯이 유한하게 정해져 있어서 여러 주소가 같은 슬롯을 쓰는 것은 이 계산에서 자연스러워요. 같은 슬롯이라는 정보만으로 실제 메모리 범위가 겹친다고 결론내리면 안 돼요. 기록의 주소와 길이를 이용한 추가 비교가 필요해요.', 'CONFIG_KCSAN_NUM_WATCHPOINTS는 슬롯 수를 정하는 설정이에요. 한 접근에서 후보로 확인하는 수 NUM_SLOTS와는 달라요. 고정 소스의 후보 수는 3이지만 전체 슬롯 수를 무조건 3이라고 읽으면 안 돼요. 이 수업의 64는 계산을 위한 예시 설정이에요.'], [('같은 페이지 안의 주소 4096과 4097은 같은 슬롯을 고르나요?', ['아니요. 바이트마다 반드시 다른 슬롯이에요', '네. 페이지 번호가 같아 나머지도 같아요'], '정답은 두 번째예요. 페이지가 4096바이트이면 두 주소를 4096으로 정수 나누어 모두 1을 얻어요. 같은 수에 같은 나머지 계산을 하니 슬롯도 같아요.'), ('슬롯 64개일 때 페이지 1과 페이지 65가 같은 슬롯을 고를 수 있나요?', ['네. 1%64와 65%64가 모두 1이에요', '아니요. 모든 페이지는 반드시 고유 슬롯을 가져요'], '정답은 첫 번째예요. 나머지는 64페이지 간격으로 반복돼요. 같은 슬롯은 같은 실제 메모리라는 뜻이 아니므로 주소 범위를 추가로 확인해야 해요.')]), 'os1699': ('100번 칸부터 네 칸을 색칠하면 100·101·102·103이에요. 바로 옆 104번부터 색칠한 칸들과 붙어 있지만 같은 칸을 칠한 것은 아니에요.', '시작 주소와 길이로 마지막 칸을 구하고 겹침을 판단합니다.', '100부터 네 칸과 104부터 네 칸을 그리세요. 두 번째 시작을 103으로 옮겼을 때 함께 칠해지는 칸을 찾으세요.', ['matching_access는 두 메모리 접근이 같은 바이트를 하나라도 포함하는지 비교해요. addr는 시작 칸의 주소이고 size는 칸 수예요. 이 계산을 정상적인 접근 비교에 쓰려면 길이가 0보다 크고 끝 주소 계산이 정수 범위를 넘어가지 않아야 해요.', '마지막 칸은 시작+길이-1이에요. 시작 칸 자체도 첫 칸으로 세기 때문에 1을 빼요. 주소 100에서 길이 4라면 100·101·102·103 네 칸이고 마지막은 100+4-1=103이에요. 마지막을 104로 잡으면 다섯 칸을 세게 돼요.', '본문은 addr1<=end2와 addr2<=end1을 모두 확인해요. 첫 시작이 둘째 끝보다 뒤에 있으면 두 범위는 떨어져 있어요. 반대 방향도 확인해야 하므로 둘째 시작이 첫째 끝보다 뒤인지도 살펴요. 두 조건이 모두 맞아야 겹친다고 해요.', '첫 범위가 100~103이고 둘째가 104~107이면 104<=103이 거짓이어서 겹치지 않아요. 반면 둘째가 103~106이면 100<=106과 103<=103이 모두 참이에요. 이때는 103번 한 바이트를 함께 포함해요. 끝 칸도 포함하므로 같은 경계값은 겹침이에요.', '크기 0을 넣으면 자동으로 빈 범위라고 처리해 주는 함수는 아니에요. 본문에는 size==0 검사 없이 시작+길이-1 계산이 있어요. 예를 들어 첫 시작101·길이0, 둘째 시작100·길이3이면 식은 참이 될 수 있어요. 정상적인 길이 0 접근은 앞의 check_access에서 먼저 제외해요.', 'unsigned 정수는 표현 범위를 넘거나 0 아래로 내려가면 수가 돌아갈 수 있어요. 그러면 계산한 끝 주소가 일반적인 줄 위의 끝점과 달라져요. 이 작은 비교 함수에 아무 길이나 넣기보다 호출자가 길이와 주소 범위 조건을 지키는지 함께 확인해야 해요.'], [('주소100·길이4와 주소104·길이4는 겹치나요?', ['네. 바로 옆에 붙어 있으면 겹쳐요', '아니요. 첫 범위는 103에서 끝나고 다음은 104에서 시작해요'], '정답은 두 번째예요. 첫 네 칸은 100·101·102·103, 다음 네 칸은 104·105·106·107이에요. 두 범위에 함께 들어 있는 칸이 없어요.'), ('이 작은 함수는 길이 0을 넣으면 언제나 false를 돌려주나요?', ['아니요. 호출 전에 길이 0을 제외하는 조건을 확인해야 해요', '네. 본문에 길이 0이면 false라는 분기가 있어요'], '정답은 첫 번째예요. 본문에는 그 분기가 없고 시작+길이-1을 계산해요. 실제 검사 흐름의 check_access가 길이 0을 먼저 제외하므로 그 호출 조건까지 읽어야 해요.')]), 'os1700': ('찾을 물건의 후보 서랍을 골랐으면 내용이 유효한지, 원하는 종류인지, 범위가 맞는지 차례로 확인해요. 같은 서랍에 있다는 이유만으로 바로 정답이라고 할 수는 없어요.', '세 후보를 상태·접근 방향·범위 순서로 걸러내는 과정을 이해합니다.', '후보A는 예약 값, B는 읽기 기록, C는 쓰기 기록으로 놓으세요. 쓰기 기록을 찾는 상황에서 A와 B를 건너뛰고 C의 범위를 비교하는 흐름을 그리세요.', ['find_watchpoint는 현재 접근과 관련 있는 감시 기록을 찾는 함수예요. 슬롯은 기록을 담은 자리이고 후보는 아직 일치한다고 확정하지 않은 기록이에요. 고정 헤더에서 인접 설정은 1, 후보 수 NUM_SLOTS는 1+2×1=3이에요.', '이 3은 한 번의 탐색에서 살펴볼 후보 수예요. 설정된 전체 슬롯 수와 같다는 뜻은 아니에요. BUILD_BUG_ON은 커널을 만들 때 전체 슬롯 수가 3보다 작으면 잘못된 설정으로 잡도록 해요. 이 검사가 실제 기록 내용을 읽는 일까지 대신하지는 않아요.', '함수는 후보를 차례로 읽고 decode_watchpoint로 내용을 풀어요. 기록이 예약 값 0이나 1이면 해석에 실패하므로 continue해요. continue는 반복문에서 지금 후보의 남은 처리를 건너뛰고 다음 후보로 가라는 뜻이에요.', '다음 조건은 expect_write && !is_write예요. expect_write는 쓰기 기록을 찾는 중이라는 뜻이고 is_write는 후보가 쓰기 기록인지 나타내요. 쓰기 기록이 필요한데 후보가 읽기라면 건너뛰어요. 보통 읽기 접근은 상대 쓰기를 찾아야 하므로 읽기·읽기 쌍을 걸러내는 데 쓰여요.', '그 뒤에 matching_access로 두 접근 범위가 겹치는지 확인해요. 상태가 정상이고 방향도 맞더라도 범위가 떨어져 있으면 일치 후보가 아니에요. 맞는 후보를 찾으면 바로 반환하므로 매번 반드시 세 개를 끝까지 다 읽는 것은 아니에요. 끝까지 못 찾으면 NULL을 돌려줘요.', '이 수업 아래 발췌에는 보고 함수의 선언이 보이지만, 실제 탐색 순서는 kernel/kcsan/core.c의 find_watchpoint를 함께 읽은 내용이에요. 기록을 찾는 일과 최종 충돌 보고는 별도 단계예요. 후보를 찾았다는 사실만으로 모든 보고 조건이 끝났다고 단정하지 마세요.'], [('이 고정 소스에서 한 번의 탐색이 살펴볼 후보 슬롯 수는 얼마인가요?', ['전체 슬롯 수와 언제나 같아요', 'NUM_SLOTS로 정한 3개예요'], '정답은 두 번째예요. 1+2×인접 설정1=3이에요. 전체 슬롯 설정과는 별개이고, 일치 후보를 먼저 찾으면 세 개를 모두 읽기 전에 돌아갈 수 있어요.'), ('쓰기 기록을 찾는데 현재 후보가 읽기 기록이면 어떻게 하나요?', ['그 후보를 건너뛰고 다음 후보를 살펴요', '그 즉시 무조건 충돌로 보고해요'], '정답은 첫 번째예요. expect_write && !is_write이면 continue해요. 이 방향 조건을 통과한 뒤에도 실제 주소 범위가 겹치는지 확인해야 해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_420.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
